complete_rows = [2, 9, 14, 15, 18]

# New approach:
# - Complete horizontal lines stay
# - Column 4 (full vertical) stays
# - Any column that appears in ANY clearing row gets filled from its appearance to the next horizontal line

solution = [[5]*10 for _ in range(20)]

# Complete horizontal lines
for row in complete_rows:
    for c in range(10):
        solution[row][c] = 8

# Full vertical line at col 4
for row in range(20):
    solution[row][4] = 8

# For clearing rows, fill from appearance to the next complete horizontal line
# Region before line 2: rows 0,1 -> fill from row 0 to 2
# Region between lines 2-9: rows 3-8 -> fill from row 3 to 9
# Region between lines 9-14: rows 10-13 -> fill from row 10 to 14
# Region between lines 15-18: rows 16-17 -> fill from row 16 to 18
# Row 19: fill from row 19 to ? maybe 19 only or to end of grid

# Fill region 0-2
if input_grid[0][0] == 8:
    for r in range(0, 3):
        solution[r][0] = 8
if input_grid[0][6] == 8:
    for r in range(0, 3):
        solution[r][6] = 8

# Fill region 3-9  
if input_grid[5][8] == 8 or input_grid[5][9] == 8:
    for r in range(3, 10):
        solution[r][8] = 8
        solution[r][9] = 8
if input_grid[7][2] == 8:
    for r in range(3, 10):
        solution[r][2] = 8
if input_grid[7][3] == 8:
    for r in range(3, 10):
        solution[r][3] = 8
if input_grid[7][7] == 8:
    for r in range(3, 10):
        solution[r][7] = 8

# Fill region 10-14
if input_grid[11][1] == 8:
    for r in range(10, 15):
        solution[r][1] = 8
if input_grid[11][6] == 8:
    for r in range(10, 15):
        solution[r][6] = 8
if input_grid[13][1] == 8:
    for r in range(10, 15):
        solution[r][1] = 8

# Fill region 16-19
if input_grid[17][7] == 8:
    for r in range(16, 20):
        solution[r][7] = 8
if input_grid[19][3] == 8:
    for r in range(16, 20):
        solution[r][3] = 8

print("=== Solution ===")
for row in solution:
    print(' '.join(str(c) for c in row))

import json
print(json.dumps(solution))

